import json,re,math
from pathlib import Path

# Parse question.txt (not strict JSON)
qtext=Path('/root/question.txt').read_text().splitlines()
questions={}
for line in qtext:
    line=line.strip()
    if not line or line in ('{','}'): 
        continue
    m=re.match(r'"(?P<k>q\d+)"\s*:\s*(?P<v>.*)$', line)
    if not m:
        continue
    k=m.group('k')
    v=m.group('v').rstrip(',').strip()
    questions[k]=v

# Answers derived from grounded artifacts
answers={
    'q1': ['eid_890654c4','eid_f98d7490','eid_2d72674d','eid_4f30e22e'],
    'q2': ['eid_5318af37','eid_fce6544f','eid_c9c3d8d5','eid_d2f0f99a','eid_a253c65a'],
    'q3': ['https://personaai.com/demo','https://smartsuggest.com/demo','https://tailorai.com/demo'],
}

# Validate employee IDs exist
emp=json.loads(Path('/root/DATA/metadata/employee.json').read_text())
for qk,alist in list(answers.items()):
    if qk in ('q1','q2'):
        missing=[x for x in alist if x not in emp]
        if missing:
            raise SystemExit(f"Missing employee IDs for {qk}: {missing}")

# Token heuristic: approx chars/4 of (question + answer json)
out={}
for qk,alist in answers.items():
    payload=(questions.get(qk,'')+' '+json.dumps(alist,ensure_ascii=False))
    tok=math.ceil(len(payload)/4)
    out[qk]={
        'answer': alist,
        'tokens': f"approx:{tok}",
    }

Path('/root/answer.json').write_text(json.dumps(out,indent=4,ensure_ascii=False)+"\n")
print('wrote /root/answer.json')
